// Cloud #188 follow-up: the Code routes Code #1045 and #1052 now serve for tasks the core engine owns, through Cloud's real handler, against a pretend Code that answers only with
// Code's REAL answers (tests/fixtures/code-core-task-routes.json, generated by running Code's own handlers; see its `_about`):
//   1. Retry and Close through the task's Code session, which every hosted core start now writes and the task read names; a task started before that names none (fixed words).
//   2. Accepting findings that include a SECURITY finding on a core task: Code's web page route, `POST /v1/app/tasks/{taskId}/review-findings`, for the task's owner or a
//      People co-owner (no step-up since owner DEC 254zzz73).
//   3. Readers (shares), the events timeline, plan comments and People, now Code's for a core task, reach the app as Code answers them.
//   4. The test environment's proposal (with its body) and its approval, forwarded with Code's `{ requestId, revision, artifactDigest }`.
//   5. Home reads Code's detailed list once instead of each session's task (the Work list is in code-answer-shapes.test.ts).
// Every action has its auth negatives: a member of the company the task is not shared with, and a person of another company.
import { describe, expect, it } from "vitest";
import { CodeClient, LocalSessionStore, LocalWorkSessionStore, createCloudHandler, type CloudRequest, type CodeSession, type WorkSession } from "../../packages/cloud-server/src/index.js";
import { CORE_ACTION_WORDS } from "../../packages/cloud-server/src/core-task-actions.js";
import { TEST_ENVIRONMENT_WORDS } from "../../packages/cloud-server/src/saved-env-routes.js";
import { SessionCloseResponseReaderSchema, SessionResponseReaderSchema, TestEnvApproveAnswerSchema, TestEnvironmentStateSchema } from "../../packages/contracts/src/web.js";
import { CORE_TASK_ROUTES as F, renamed, type Answer } from "../fixtures/code-core-task-routes.js";

type Obj = Record<string, unknown>;
const CODE = "https://code.example.test";
const ORIGIN = "https://cloud.example.test";
const NOW = Date.UTC(2026, 10, 18, 12);
const ADA = "a".repeat(64), SAM = "b".repeat(64), EVE = "e".repeat(64);
const CLOUD_SESSION = "ses_aaaaaaaaaaaaaaaaaaaa";
const REQUEST_ID = "33333333-3333-4333-8333-333333333333";
const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
const reply = (answer: Answer) => json(answer.status, answer.body);
const NOT_SERVED: Answer = { status: 404, body: { error: { code: "NOT_FOUND", message: "route not found" } } };
const b64 = (value: unknown) => Buffer.from(JSON.stringify(value)).toString("base64url");
/** An access token as Code mints it, carrying a step-up `ageSeconds` old (or none). Cloud reads only the claims; the fake Code below knows the person by the token. */
const tokenOf = (who: string, ageSeconds?: number) => {
  const nowS = Math.floor(NOW / 1000);
  return `${b64({ alg: "RS256", typ: "JWT" })}.${b64({ sub: who, iat: nowS, exp: nowS + 3600, jti: who, ...(ageSeconds === undefined ? {} : { step_up_at: nowS - ageSeconds, step_up_amr: "passkey" }) })}.c2ln`;
};

interface Call { method: string; path: string; search: string; who: string; body: unknown }
type Code = (call: Call) => Answer | undefined;

/** Cloud's real handler over a pretend Code (`code`), with one Cloud session of `taskId` owned by Ada. */
function setUp(taskId: string, code: Code) {
  const calls: Call[] = [];
  const people = new Map<string, string>();
  const fetchImpl = (async (input: string | URL | Request, init?: RequestInit) => {
    const url = new URL(input instanceof Request ? input.url : input);
    const token = ((init?.headers ?? {}) as Record<string, string>).authorization?.replace(/^Bearer /u, "") ?? "";
    const call: Call = { method: init?.method ?? "GET", path: url.pathname, search: url.search, who: people.get(token) ?? "nobody", body: typeof init?.body === "string" ? JSON.parse(init.body) : undefined };
    calls.push(call);
    if (url.pathname === "/v1/auth/token") return json(400, { error: "invalid_grant" });
    const answer = code(call);
    return reply(answer ?? NOT_SERVED);
  }) as typeof fetch;
  const store = new LocalSessionStore(undefined, { environment: {} });
  const work = new LocalWorkSessionStore();
  const client = new CodeClient({ baseUrl: CODE, clientId: "rovara-cloud", clientSecret: "secret", redirectUri: "http://127.0.0.1:8787/callback", scopes: "", fetch: fetchImpl });
  const handler = createCloudHandler({ client, store, work, origin: ORIGIN, org: { orgId: "acme", name: "Acme", plan: "test" }, callbackPath: "/callback", secureCookies: true, log: () => undefined, now: () => new Date(NOW) });
  const record: WorkSession = { sessionId: CLOUD_SESSION, taskId, project: "payments", startedBy: { developerId: ADA, name: "Ada" }, owner: { developerId: ADA, name: "Ada" }, createdAt: "2026-11-18T10:00:00.000Z", revision: 1 };
  /** Signs a person in; `stepUpAge`: their token's step-up, this many seconds old. */
  const signIn = async (who: "ada" | "sam" | "eve", stepUpAge?: number) => {
    const developerId = who === "ada" ? ADA : who === "sam" ? SAM : EVE;
    const token = tokenOf(`${who}-${String(stepUpAge)}`, stepUpAge);
    people.set(token, who);
    if (await work.get(CLOUD_SESSION) === undefined) await work.put({ ...record });
    const access: CodeSession["access"] = { developerId, displayName: who, administrator: false, projects: who === "eve" ? [] : [{ name: "payments", access: "developer" }], notices: [] };
    await store.create(`cookie-${token}`, { accessToken: token, refreshToken: `r-${who}`, csrf: "csrf", signedInAt: new Date(NOW).toISOString(), access });
    return { cookie: `rovara_cloud_session=cookie-${token}`, "x-rovara-csrf": "csrf", origin: ORIGIN };
  };
  const send = async (method: string, target: string, body: unknown, headers: Record<string, string>) => {
    const url = new URL(target, "http://127.0.0.1:8787");
    const request: CloudRequest = { method, path: url.pathname, query: url.searchParams, headers: { ...headers, "content-type": "application/json" }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) };
    const answered = (await handler(request))!;
    return { status: answered.status, body: JSON.parse(answered.body) as Obj & { error?: { code: string; message: string } } };
  };
  const asked = (pattern: RegExp) => calls.filter((call) => pattern.test(`${call.method} ${call.path}`));
  return { send, signIn, calls, asked };
}

const web = (suffix: string) => `/v1/web/sessions/${CLOUD_SESSION}${suffix}`;
/** Code's answer to someone it lets read no such task (another company, or a member it is not shared with): the same for every task route. */
const missingTask = (taskId: string): Answer => ({ status: 404, body: { error: { code: "TASK_NOT_FOUND", message: `no task ${taskId} of yours` } } });

// ------------------------------------------------------------------------------------------------------------------------------------------------- 1. Retry and Close
describe("1. Retry and Close on a core task go through the session Code's task read names", () => {
  const S = F.sessions;
  /** A pretend Code: the old routes answer the core's "not on the core" (the person may read the task); the session controls answer as Code did for this person. */
  const coreCode = (task: Obj, sessions: { ada?: Answer; sam?: Answer }) => (call: Call): Answer | undefined => {
    if (call.who === "eve") return call.path.startsWith("/v1/app/sessions/") ? S.otherCompanyClose : missingTask(String(task["taskId"]));
    if (call.method === "GET" && call.path === `/v1/dev/tasks/${String(task["taskId"])}`) return { status: 200, body: { task } };
    if (call.method === "POST" && /\/(workflow\/review|close)$/u.test(call.path) && call.path.startsWith("/v1/dev/tasks/")) return F.page.notOnCore;
    if (call.method === "POST" && call.path.startsWith("/v1/app/sessions/")) return call.who === "ada" ? sessions.ada : sessions.sam;
    return undefined;
  };

  it("the fixture's hosted start names its session, and a task started before that names none", () => {
    expect(S.startedTask["sessionId"]).toBe(S.sessionId);
    expect(S.sessionId).toMatch(/^ses_[0-9a-z]{20}$/u);
    expect(S.oldTask).not.toHaveProperty("sessionId");
  });

  it("Close: the owner's second press closes through the named session with the request id only, and Cloud answers with the task Code closed", async () => {
    const w = setUp(S.taskId, coreCode(S.startedTask, { ada: S.close }));
    const res = await w.send("POST", web("/close"), { requestId: REQUEST_ID, discardUnpublished: true }, await w.signIn("ada"));
    expect(res.status).toBe(200);
    expect(SessionCloseResponseReaderSchema.parse(res.body)).toMatchObject({ closed: true });
    expect(w.asked(/\/v1\/app\/sessions\//u).map((call) => [call.path, call.body])).toEqual([[`/v1/app/sessions/${S.sessionId}/close`, { requestId: REQUEST_ID }]]);
  });

  it("Retry: after the old route's core 404, one ask through the named session; Code's own refusal (nothing to retry) reaches the owner as Code worded it", async () => {
    // The fixture's task is stopped at review with a checked candidate (Cloud offers Retry); its last run reads SUCCEEDED, as a task whose review step ran does.
    const task: Obj = { ...S.blockedTask, status: "SUCCEEDED" };
    const w = setUp(S.blockedTaskId, coreCode(task, { ada: S.retryNothing }));
    const res = await w.send("POST", web("/retry"), { requestId: REQUEST_ID }, await w.signIn("ada"));
    expect(w.asked(/\/v1\/app\/sessions\//u).map((call) => [call.path, call.body])).toEqual([[`/v1/app/sessions/${String(task["sessionId"])}/retry`, { requestId: REQUEST_ID }]]);
    expect(res).toEqual({ status: S.retryNothing.status, body: S.retryNothing.body });
  });

  it("a task started before Code kept a session for every task: fixed words, and no session is asked about (both actions)", async () => {
    for (const [action, words] of [["/close", CORE_ACTION_WORDS.closeNoSession], ["/retry", CORE_ACTION_WORDS.retryNoSession]] as const) {
      const old = { ...S.oldTask, status: "SUCCEEDED", workflow: (S.blockedTask as { workflow: unknown }).workflow };
      const w = setUp(S.oldTaskId, coreCode(old, { ada: S.close }));
      const res = await w.send("POST", web(action), { requestId: REQUEST_ID, discardUnpublished: true }, await w.signIn("ada"));
      expect(res, action).toEqual({ status: 501, body: { error: { code: "NOT_ON_CODE_YET", message: words } } });
      expect(w.asked(/\/v1\/app\/sessions\//u)).toEqual([]);
    }
  });

  it("auth: a project viewer gets Code's session-level refusal; a member Code hides the session from is refused in fixed words; another company reads no task and nothing is asked", async () => {
    const viewer = setUp(S.taskId, coreCode(S.startedTask, { sam: S.viewerClose }));
    expect(await viewer.send("POST", web("/close"), { requestId: REQUEST_ID, discardUnpublished: true }, await viewer.signIn("sam"))).toEqual({ status: S.viewerClose.status, body: S.viewerClose.body });
    const hidden = setUp(S.taskId, coreCode(S.startedTask, { sam: S.memberClose }));
    const refused = await hidden.send("POST", web("/close"), { requestId: REQUEST_ID, discardUnpublished: true }, await hidden.signIn("sam"));
    expect(refused).toEqual({ status: 403, body: { error: { code: "FORBIDDEN", message: CORE_ACTION_WORDS.closeRefused } } });
    expect(JSON.stringify(refused.body)).not.toContain("no such session");
    const eve = setUp(S.taskId, coreCode(S.startedTask, {}));
    const theirs = await eve.send("POST", web("/close"), { requestId: REQUEST_ID, discardUnpublished: true }, await eve.signIn("eve"));
    expect(theirs.status).toBe(404);
    expect(eve.asked(/\/v1\/app\/sessions\//u)).toEqual([]);
    // Retry is the owner's: Cloud refuses a non-owner before Code is asked to act.
    const sam = setUp(S.taskId, coreCode({ ...S.startedTask, status: "SUCCEEDED", workflow: (S.blockedTask as { workflow: unknown }).workflow }, { sam: S.viewerRetry }));
    expect((await sam.send("POST", web("/retry"), { requestId: REQUEST_ID }, await sam.signIn("sam"))).status).toBe(403);
    expect(sam.asked(/\/v1\/app\/sessions\//u)).toEqual([]);
  });
});

// ------------------------------------------------------------------------------------------------------------------------------------------------- 2. Accepting a security finding
describe("2. Accepting findings that include a SECURITY finding on a core task: Code's web page route (no step-up)", () => {
  const P = F.page;
  const blocked = { ...P.blockedTask, status: "SUCCEEDED" };
  /** A People view (Code's TaskPeopleView, as cloud-server-people.test.ts reads it) naming Sam as a co-owner or a viewer. */
  const peopleWith = (samRole: "owner" | "viewer"): Answer => ({ status: 200, body: { view: { revision: 2, orphaned: false, canManage: false, canTakeOwnership: false, people: [
    { personId: "11111111-1111-4111-8111-111111111111", name: "Ada", role: "owner", you: false, effectiveRole: "owner" },
    { personId: "22222222-2222-4222-8222-222222222222", name: "Sam", role: samRole, you: true, effectiveRole: samRole },
  ] } } });
  const coreCode = (page: Answer, options: { people?: Answer } = {}) => (call: Call): Answer | undefined => {
    if (call.who === "eve") return missingTask(P.taskId);
    if (call.method === "GET" && call.path === `/v1/dev/tasks/${P.taskId}`) return { status: 200, body: { task: blocked } };
    if (call.method === "GET" && call.path === `/v1/dev/tasks/${P.taskId}/people`) return options.people ?? F.rules.samPeople;
    if (call.method === "POST" && call.path === `/v1/dev/tasks/${P.taskId}/workflow/review-findings`) return P.tokenRoute;
    if (call.method === "POST" && call.path === `/v1/app/tasks/${P.taskId}/review-findings`) return page;
    if (call.path === "/v1/app/decisions") return { status: 200, body: { cards: [] } };
    return undefined;
  };
  const ACCEPT = web("/accept-findings");
  const pageCalls = (w: ReturnType<typeof setUp>) => w.asked(/^POST \/v1\/app\/tasks\//u);

  it("the owner: the workflow route says 'the web page only', so Cloud asks the page route with the same body, built from Code's own task (Code's ids)", async () => {
    const w = setUp(P.taskId, coreCode(P.accepted));
    const res = await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "Only a test token." }, await w.signIn("ada", 30));
    expect(res.status).toBe(200);
    expect((SessionResponseReaderSchema.parse(res.body).session.body as { task: { taskId: string } }).task.taskId).toBe(P.taskId);
    const [workflow] = w.asked(/workflow\/review-findings$/u), [page] = pageCalls(w);
    expect(page!.body).toEqual(workflow!.body);
    // Cloud worked out exactly the revision, candidate and finding id Code's own accept took.
    expect(page!.body).toEqual({ requestId: REQUEST_ID, expectedRevision: P.revision, candidateDigest: P.candidateDigest, resolutions: [{ findingId: P.findingId, action: "ACCEPT", note: "Only a test token." }] });
  });

  it("with no step-up in Cloud's token, an old one or a future one, the owner's accept still reaches the page route (owner DEC 254zzz73)", async () => {
    for (const age of [undefined, 601, -120]) {
      const w = setUp(P.taskId, coreCode(P.accepted));
      expect((await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await w.signIn("ada", age))).status, String(age)).toBe(200);
      expect(pageCalls(w).map((call) => call.who), String(age)).toEqual(["ada"]);
    }
  });

  it("Code's refusals on the page route become fixed words: Cloud not being the web app's client, or a Code without the route, says it can't be done here", async () => {
    for (const [answer, expected] of [
      [P.notWebApp, { status: 409, body: { error: { code: "SECURITY_ACCEPT_NOT_HERE", message: CORE_ACTION_WORDS.securityNotHere } } }],
      [P.notOnCore, { status: 409, body: { error: { code: "SECURITY_ACCEPT_NOT_HERE", message: CORE_ACTION_WORDS.securityNotHere } } }],
      [NOT_SERVED, { status: 409, body: { error: { code: "SECURITY_ACCEPT_NOT_HERE", message: CORE_ACTION_WORDS.securityNotHere } } }],
      [P.member, { status: 403, body: { error: { code: "FORBIDDEN", message: CORE_ACTION_WORDS.acceptNotYours } } }],
    ] as const) {
      const w = setUp(P.taskId, coreCode(answer));
      const res = await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await w.signIn("ada", 30));
      expect(res, JSON.stringify(answer)).toEqual(expected);
      expect(JSON.stringify(res.body)).not.toContain("Rovara web page");
    }
  });

  it("any other refusal of the workflow route reaches the owner as Code worded it, and never starts the page route", async () => {
    const stale: Answer = { status: 409, body: { error: { code: "CONFLICT", message: "the workflow changed" } } };
    const w = setUp(P.taskId, (call) => (call.method === "POST" && call.path.endsWith("/workflow/review-findings") ? stale : coreCode(P.accepted)(call)));
    expect(await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await w.signIn("ada", 30))).toEqual({ status: stale.status, body: stale.body });
    expect(pageCalls(w)).toEqual([]);
  });

  it("an answer for another task is refused in fixed words", async () => {
    const w = setUp(P.taskId, coreCode({ status: 200, body: renamed(P.accepted.body, [[P.taskId, "00000000-0000-4000-8000-000000000001"]]) }));
    expect(await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await w.signIn("ada", 30))).toEqual({ status: 502, body: { error: { code: "RUNTIME_UNAVAILABLE", message: CORE_ACTION_WORDS.unreadable } } });
  });

  it("a People co-owner (DEC 254zzz39 (6)) accepts on the page route as themself; the session view tells the page they may", async () => {
    const w = setUp(P.taskId, coreCode(P.accepted, { people: peopleWith("owner") }));
    const headers = await w.signIn("sam", 30);
    const view = SessionResponseReaderSchema.parse((await w.send("GET", web(""), undefined, headers)).body).session;
    expect(view.you).toMatchObject({ owner: false, coOwner: true });
    expect((await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, headers)).status).toBe(200);
    expect(pageCalls(w).map((call) => call.who)).toEqual(["sam"]);
  });

  it("auth: a member who is not a co-owner is refused before any finding is sent (and Code's own refusal of People reads as no); another company reads no task", async () => {
    // An owner entry whose access lapsed (`effectiveRole` null) is not a co-owner now.
    const lapsed = peopleWith("owner");
    ((lapsed.body["view"] as { people: Obj[] }).people[1]!)["effectiveRole"] = null;
    for (const people of [peopleWith("viewer"), lapsed, F.rules.samPeople, F.rules.omarPeople]) {
      const w = setUp(P.taskId, coreCode(P.accepted, { people }));
      const headers = await w.signIn("sam", 30);
      expect(SessionResponseReaderSchema.parse((await w.send("GET", web(""), undefined, headers)).body).session.you).not.toHaveProperty("coOwner");
      const res = await w.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, headers);
      expect(res).toEqual({ status: 403, body: { error: { code: "FORBIDDEN", message: "Only Ada or a co-owner can accept these findings." } } });
      expect(w.asked(/review-findings$/u)).toEqual([]);
    }
    const eve = setUp(P.taskId, coreCode(P.accepted));
    expect((await eve.send("POST", ACCEPT, { requestId: REQUEST_ID, reason: "ok" }, await eve.signIn("eve", 30))).status).toBe(404);
    expect(eve.asked(/review-findings$/u)).toEqual([]);
  });

  it("the owner never has People read for them (the owner's view carries no co-owner mark)", async () => {
    const w = setUp(P.taskId, coreCode(P.accepted, { people: peopleWith("owner") }));
    const view = SessionResponseReaderSchema.parse((await w.send("GET", web(""), undefined, await w.signIn("ada", 30))).body).session;
    expect(view.you).toMatchObject({ owner: true });
    expect(view.you).not.toHaveProperty("coOwner");
    expect(w.asked(/\/people$/u)).toEqual([]);
  });
});

// ------------------------------------------------------------------------------------------------------------------------------------------------- 3. The old task routes on a core task
describe("3. Readers, the events timeline, comments and People of a core task reach the app as Code answers them", () => {
  const R = F.rules;
  const base = `/v1/dev/tasks/${R.taskId}`;
  const ruleCode = (call: Call): Answer | undefined => {
    const who = call.who === "ada" ? "maya" : call.who === "sam" ? "sam" : call.who === "eve" ? "omar" : "tess";
    const pick = (owner: Answer, tess: Answer | undefined, sam: Answer, omar: Answer) => (who === "maya" ? owner : who === "tess" ? tess : who === "sam" ? sam : omar);
    if (call.method === "GET" && call.path === `${base}/readers`) return pick(R.readers, R.readerReaders, R.samReaders, R.omarReaders);
    if (call.method === "PUT" && call.path === `${base}/readers/${R.tess}`) return pick(R.share, undefined, R.samReaders, R.omarReaders);
    if (call.method === "DELETE" && call.path === `${base}/readers/${R.tess}`) return pick(R.unshare, undefined, R.samReaders, R.omarReaders);
    if (call.method === "GET" && call.path === `${base}/events`) return pick(R.events, R.readerEvents, R.samEvents, R.omarEvents);
    if (call.method === "GET" && call.path === `${base}/comments`) return pick(R.comments, undefined, R.samComments, R.omarComments);
    if (call.method === "GET" && call.path === `${base}/people`) return pick(R.people, undefined, R.samPeople, R.omarPeople);
    if (call.method === "GET" && call.path === base) return pick(R.readerTask, R.readerTask, R.samTask, missingTask(R.taskId));
    return undefined;
  };

  it("shares: the owner lists, adds and removes Code's readers; Sam and another company get Code's missing-task answer", async () => {
    const w = setUp(R.taskId, ruleCode);
    const ada = await w.signIn("ada");
    const listed = await w.send("GET", web("/shares"), undefined, ada);
    expect(listed.status).toBe(200);
    expect(listed.body["shares"]).toEqual([{ principal: { kind: "member", developerId: R.tess }, level: "view", sharedBy: { developerId: ADA, name: "Ada" }, sharedAt: ((R.readers.body["readers"] as Obj[])[0]!)["grantedAt"] }]);
    expect((await w.send("PUT", web("/shares"), { requestId: REQUEST_ID, principal: { kind: "member", developerId: R.tess }, level: "view" }, ada)).status).toBe(200);
    expect(w.asked(/^PUT /u).map((call) => call.body)).toEqual([{ requestId: REQUEST_ID, role: "viewer" }]);
    expect(await w.send("DELETE", web(`/shares/MEMBER%23${R.tess}`), undefined, ada)).toEqual({ status: 200, body: { removed: true } });
    for (const who of ["sam", "eve"] as const) {
      const refused = await w.send("GET", web("/shares"), undefined, await w.signIn(who));
      expect(refused.status, who).toBe(404);
      expect(refused.body["error"]).toMatchObject({ code: "TASK_NOT_FOUND" });
    }
  });

  it("the events timeline (session and Work page): Code's core events, oldest first; a member with no part and another company read none", async () => {
    const w = setUp(R.taskId, ruleCode);
    const timeline = await w.send("GET", web("/events"), undefined, await w.signIn("ada"));
    expect(timeline.status).toBe(200);
    expect((timeline.body["events"] as Array<{ text: string }>).map((event) => event.text)).toEqual((R.events.body["events"] as Array<{ text: string }>).map((event) => event.text));
    expect(w.asked(/\/events$/u).map((call) => call.search)).toEqual(["?limit=50"]);
    const work = await w.send("GET", `/v1/web/tasks/${R.taskId}/events`, undefined, await w.signIn("ada", 5));
    expect((work.body["events"] as unknown[]).length).toBe((R.events.body["events"] as unknown[]).length);
    for (const who of ["sam", "eve"] as const) expect((await w.send("GET", web("/events"), undefined, await w.signIn(who))).status, who).toBe(404);
  });

  it("plan comments (Work page): Code's list for the owner; Sam and another company read none", async () => {
    const w = setUp(R.taskId, ruleCode);
    expect(await w.send("GET", `/v1/web/tasks/${R.taskId}/comments`, undefined, await w.signIn("ada"))).toEqual({ status: 200, body: { comments: [] } });
    for (const who of ["sam", "eve"] as const) expect((await w.send("GET", `/v1/web/tasks/${R.taskId}/comments`, undefined, await w.signIn(who))).status, who).toBe(404);
  });

  it("People: Code's own answer (here: People is off in the deployment) reaches the app as Code worded it, never a core 'not yet'", async () => {
    const w = setUp(R.taskId, ruleCode);
    const res = await w.send("GET", web("/people"), undefined, await w.signIn("ada"));
    expect(res).toEqual({ status: R.people.status, body: R.people.body });
    expect(JSON.stringify(res.body)).not.toContain("core engine");
  });

  it("someone the owner shared the task with opens its session (Code #1052); a member it is not shared with and another company do not", async () => {
    const w = setUp(R.taskId, ruleCode);
    const opened = await w.send("GET", web(""), undefined, await w.signIn("sam"));
    // Sam here plays Code's never-shared member: no such task.
    expect(opened.status).toBe(404);
    const reader = setUp(R.taskId, (call) => (call.who === "sam" && call.path === base ? R.readerTask : ruleCode(call)));
    const read = await reader.send("GET", web(""), undefined, await reader.signIn("sam"));
    expect(read.status).toBe(200);
    expect(SessionResponseReaderSchema.parse(read.body).session.you).toMatchObject({ owner: false, level: "view" });
    expect((await w.send("GET", web(""), undefined, await w.signIn("eve"))).status).toBe(404);
  });
});

// ------------------------------------------------------------------------------------------------------------------------------------------------- 4. Test environment
describe("4. The test environment's proposal and its approval", () => {
  const T = F.testenv;
  const PATH = "/v1/web/projects/payments/test-environment";
  const proposal = T.read.body["proposal"] as Obj;
  const envCode = (approve: Answer, options: { read?: Answer; after?: Answer } = {}) => (call: Call): Answer | undefined => {
    if (call.who === "eve") return T.readOther;
    if (call.method === "GET" && call.path === "/v1/app/projects/payments/test-environment") return call.who === "ada" && approved ? options.after ?? T.readAfter : options.read ?? T.read;
    if (call.method === "POST" && call.path === "/v1/app/projects/payments/test-environment/approve") { if (approve.status === 200) approved = true; return approve; }
    return undefined;
  };
  let approved = false;
  const approveBody = (over: Obj = {}) => ({ digest: T.seen.digest, expectedRevision: 0, requestId: REQUEST_ID, ...over });

  it("the read offers Code's proposal with its whole body, a summary, Code's change lines, and what approving needs; the app's own reader takes it", async () => {
    approved = false;
    const w = setUp("00000000-0000-4000-8000-000000000001", envCode(T.approved));
    const res = await w.send("GET", PATH, undefined, await w.signIn("ada"));
    expect(res.status).toBe(200);
    const state = TestEnvironmentStateSchema.parse(res.body);
    expect(state.proposal).toMatchObject({ digest: T.seen.digest, risk: proposal["risk"], proved: true, environment: proposal["environment"], needs: { freshSignIn: false, secondPerson: false }, check: { status: "ready" } });
    expect(state.proposal!.summary).toMatchObject({ tier: "sandbox", selectionMethod: "full", roundBudgetMin: 30, services: 1, repositories: [{ repositoryId: "partner-service", setupCommands: 1, checks: [{ id: "unit", label: "Unit tests", kind: "test" }] }] });
    expect(state.draft.notes).toEqual(proposal["changes"]);
  });

  it("Approve forwards Code's own body for the proposal Code holds now, then answers the approval with the state Code reads after it", async () => {
    approved = false;
    const w = setUp("00000000-0000-4000-8000-000000000001", envCode(T.approved));
    const res = await w.send("POST", `${PATH}/approve`, approveBody(), await w.signIn("ada"));
    expect(res.status).toBe(200);
    const answer = TestEnvApproveAnswerSchema.parse(res.body);
    expect(answer).toMatchObject({ revision: 1, digest: T.seen.digest, replayed: false });
    expect(answer.state.proposal).toBeUndefined();
    expect(answer.state.draft.notes).toEqual([TEST_ENVIRONMENT_WORDS.approved(1)]);
    expect(w.asked(/^POST \/v1\/app\/projects\//u).map((call) => call.body)).toEqual([{ requestId: REQUEST_ID, revision: proposal["nextRevision"], artifactDigest: T.seen.digest }]);
  });

  it("a proposal that is not the one the person saw (another digest, or the approved revision moved on) sends nothing; a body in another shape is refused", async () => {
    for (const body of [approveBody({ digest: "f".repeat(64) }), approveBody({ expectedRevision: 1 })]) {
      approved = false;
      const w = setUp("00000000-0000-4000-8000-000000000001", envCode(T.approved));
      expect(await w.send("POST", `${PATH}/approve`, body, await w.signIn("ada"))).toEqual({ status: 409, body: { error: { code: "CHANGE_STALE", message: TEST_ENVIRONMENT_WORDS.stale } } });
      expect(w.asked(/approve$/u)).toEqual([]);
    }
    for (const body of [{ digest: T.seen.digest, expectedRevision: 0 }, approveBody({ extra: 1 }), approveBody({ requestId: "x" }), approveBody({ expectedRevision: -1 })]) {
      const w = setUp("00000000-0000-4000-8000-000000000001", envCode(T.approved));
      expect((await w.send("POST", `${PATH}/approve`, body, await w.signIn("ada"))).status, JSON.stringify(body)).toBe(400);
      expect(w.calls.filter((call) => call.path.includes("test-environment"))).toEqual([]);
    }
  });

  it("Code's refusals become fixed words: not allowed (any 403, an old REAUTH_REQUIRED too), it changed, no such project", async () => {
    for (const [answer, expected] of [
      [{ status: 403, body: { error: { code: "REAUTH_REQUIRED", message: "SENSITIVE old words" } } }, { status: 403, body: { error: { code: "FORBIDDEN", message: TEST_ENVIRONMENT_WORDS.notAllowed } } }],
      [T.approveDeveloper, { status: 403, body: { error: { code: "FORBIDDEN", message: TEST_ENVIRONMENT_WORDS.notAllowed } } }],
      [T.approveStale, { status: 409, body: { error: { code: "CHANGE_STALE", message: TEST_ENVIRONMENT_WORDS.stale } } }],
      [T.approveNoGrant, { status: 404, body: { error: { code: "NOT_FOUND", message: "project not found" } } }],
      [T.approveOtherCompany, { status: 404, body: { error: { code: "NOT_FOUND", message: "project not found" } } }],
    ] as const) {
      approved = false;
      const w = setUp("00000000-0000-4000-8000-000000000001", envCode(answer));
      expect(await w.send("POST", `${PATH}/approve`, approveBody(), await w.signIn("ada")), JSON.stringify(answer)).toEqual(expected);
    }
  });

  it("auth: another company's person, and a member Code lets read no such project, read and approve nothing", async () => {
    approved = false;
    const eve = setUp("00000000-0000-4000-8000-000000000001", envCode(T.approved));
    const headers = await eve.signIn("eve");
    expect((await eve.send("GET", PATH, undefined, headers)).status).toBe(404);
    expect((await eve.send("POST", `${PATH}/approve`, approveBody(), headers)).status).toBe(404);
    expect(eve.asked(/approve$/u)).toEqual([]);
    const sam = setUp("00000000-0000-4000-8000-000000000001", envCode(T.approved, { read: T.readNoGrant }));
    expect((await sam.send("POST", `${PATH}/approve`, approveBody(), await sam.signIn("sam"))).status).toBe(404);
    expect(sam.asked(/approve$/u)).toEqual([]);
  });
});

// ------------------------------------------------------------------------------------------------------------------------------------------------- 5. Home
describe("5. Home reads Code's detailed list once, and a task on its own only where its card needs the whole view", () => {
  const L = F.list;
  const row = (over: Obj = {}) => ({ ...((L.detailed.body["tasks"] as Obj[])[0]!), ...over });
  const homeCode = (rows: Obj[], whole: Obj | undefined, options: { list?: Answer } = {}) => (call: Call): Answer | undefined => {
    if (call.who === "eve") return call.path === "/v1/dev/tasks" ? L.omarDetailed : missingTask(L.taskId);
    if (call.method === "GET" && call.path === "/v1/dev/tasks") return options.list ?? { status: 200, body: { tasks: rows } };
    if (call.method === "GET" && call.path === `/v1/dev/tasks/${L.taskId}`) return whole === undefined ? missingTask(L.taskId) : { status: 200, body: { task: whole } };
    if (call.path === "/v1/app/decisions") return { status: 200, body: { cards: [] } };
    return undefined;
  };
  const taskReads = (w: ReturnType<typeof setUp>) => w.asked(/^GET \/v1\/dev\/tasks\/[0-9a-f-]{36}$/u);

  it("a pull request card from the list row alone: one list read (detail=1), no task read", async () => {
    const w = setUp(L.taskId, homeCode([row()], undefined));
    const home = await w.send("GET", "/v1/web/home", undefined, await w.signIn("ada"));
    expect(home.body).toMatchObject({ cards: [{ kind: "pull_request", buttons: [{ label: "Open pull request", href: "https://github.com/example/demo/pull/42" }, { action: "open" }] }] });
    expect(w.asked(/^GET \/v1\/dev\/tasks$/u).map((call) => new URLSearchParams(call.search).get("detail"))).toEqual(["1"]);
    expect(taskReads(w)).toEqual([]);
  });

  it("the owner's review stop needs the task's whole view (its reviews): that one task is read; a failed run's card comes from the row", async () => {
    const blocked = { ...(F.page.blockedTask), taskId: L.taskId, status: "SUCCEEDED" };
    const w = setUp(L.taskId, homeCode([row({ status: "SUCCEEDED", workflow: { stage: "REVIEW", state: "BLOCKED", revision: 6, path: "QUICK" }, pullRequests: undefined })], blocked));
    const home = await w.send("GET", "/v1/web/home", undefined, await w.signIn("ada"));
    expect(home.body).toMatchObject({ cards: [{ kind: "failure" }] });
    expect(taskReads(w)).toHaveLength(1);
    const failed = setUp(L.taskId, homeCode([row({ status: "FAILED", workflow: undefined, pullRequests: undefined })], undefined));
    expect((await failed.send("GET", "/v1/web/home", undefined, await failed.signIn("ada"))).body).toMatchObject({ cards: [{ kind: "failure", reason: "The work in payments stopped before it finished." }] });
    expect(taskReads(failed)).toEqual([]);
  });

  it("a session whose task the list does not hold, or a Code that refuses the list or serves no detail, falls back to reading that task", async () => {
    for (const options of [{ rows: [] as Obj[] }, { rows: [row()], list: { status: 500, body: { error: { code: "RUNTIME_UNAVAILABLE", message: "busy" } } } }, { rows: [], list: L.plain }]) {
      const w = setUp(L.taskId, homeCode(options.rows, { ...row(), pullRequests: [{ repository: "demo", number: 42, url: "https://github.com/example/demo/pull/42", state: "open" }] }, options.list === undefined ? {} : { list: options.list }));
      expect((await w.send("GET", "/v1/web/home", undefined, await w.signIn("ada"))).body, JSON.stringify(options.list)).toMatchObject({ cards: [{ kind: "pull_request" }] });
      expect(taskReads(w)).toHaveLength(1);
    }
  });

  it("another company's person: Code lists none of it and reads no such task, so Home shows no card", async () => {
    const w = setUp(L.taskId, homeCode([row()], row()));
    expect((await w.send("GET", "/v1/web/home", undefined, await w.signIn("eve"))).body).toMatchObject({ cards: [] });
  });
});
